/* Banking QA 30-day source-aligned expansion. Keeps QA IDs and all prior sections. */
(function(){const arr=[{"id":"QA1D1","title":"Banking 1: Chuẩn hóa Bug Report - Viết 1 dòng hiểu ngay","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Bug là sai lệch giữa thực tế và yêu cầu, không phải ý kiến cá nhân. Trước khi viết report, xác nhận có thể tái hiện lỗi bằng dữ liệu thử và ghi thiết bị, phiên bản ứng dụng, precondition."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 1 — Chuẩn hóa Bug Report - Viết 1 dòng hiểu ngay"},{"type":"Paragraph","text":"- Lý thuyết: Cấu trúc Bug Report chuẩn Senior gồm 5 phần: \n  1. Title (Cái gì bị lỗi? Ở đâu? Trong điều kiện nào?).\n  2. Environment.\n  3. Steps to Reproduce (Đánh số 1, 2, 3... dùng động từ hành động).\n  4. Expected Result.\n  5. Actual Result. \n  *Nguyên tắc: Loại bỏ từ rườm rà, từ cảm xúc cá nhân.\n- Bài tập: Viết Bug Report cho tình huống: Trên Web Mobile Banking, khi mở tài khoản eKYC, nhập Password là \"123456\" (thiếu ký tự đặc biệt/chữ hoa). BRD yêu cầu báo lỗi đỏ ngay bên dưới ô nhập: \"Mật khẩu tối thiểu 8 ký tự, chứa chữ hoa, chữ thường và ký tự đặc biệt\". Thực tế: Không báo lỗi, bấm \"Đăng ký\" thì màn hình quay vô tận (Loading forever)."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Title: [Đăng ký eKYC][Mật khẩu yếu] Không báo validation, nút Đăng ký loading liên tục. Expected: hiển thị quy tắc mật khẩu ngay dưới input. Actual: không cảnh báo và loading không dừng. Severity: Major (cần đánh giá theo ảnh hưởng)."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Làm lại thao tác bằng dữ liệu giả và ghi 5 trường bắt buộc của bug report."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết 3 tiêu đề bug ngắn cho login, booking và watchlist, nêu Expected/Actual."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Đề xuất bằng chứng, impact, cách tái hiện và kiểm tra regression sau fix."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA1D2","title":"Banking 2: Chuẩn hóa Test Case SMART","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Test case phải đủ để người khác kiểm thử mà không cần đoán. Tách rõ dữ liệu đầu vào, tiền điều kiện và kết quả kỳ vọng; test case không đồng nghĩa checklist."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 2 — Chuẩn hóa Test Case SMART"},{"type":"Paragraph","text":"- Lý thuyết: Test Case ngắn gọn, dùng gạch đầu dòng: Test Title (Hành động + Kết quả kỳ vọng), Pre-conditions, Test Steps (1, 2, 3...), Expected Result.\n- Bài tập: Viết bộ Test Case ngắn gọn (gồm ít nhất 5 test cases phủ các trường hợp: Valid, Invalid password, Empty fields, Locked account) cho màn hình Đăng nhập App Mobile Banking."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"TC-LOGIN-01: tài khoản hợp lệ → đăng nhập thành công; TC-LOGIN-02: sai mật khẩu → báo lỗi; TC-LOGIN-03: trống ô bắt buộc → không gửi request; TC-LOGIN-04: tài khoản khóa → từ chối truy cập."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Viết 3 test cases cho đăng nhập bằng tài khoản thử."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Thêm 4 trường hợp password biên và thông báo lỗi."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Lập ma trận yêu cầu → test case và chọn regression subset."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA1D3","title":"Banking 3: Phân tích Yêu cầu (BRD/SRS) & Decision Table","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"BRD là tài liệu nhu cầu nghiệp vụ, SRS là mô tả yêu cầu hệ thống. Decision table giúp bao phủ tổ hợp điều kiện, đặc biệt khi có mức tiền, kỳ hạn và hạng khách hàng."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 3 — Phân tích Yêu cầu (BRD/SRS) & Decision Table"},{"type":"Paragraph","text":"- Lý thuyết: Dùng Decision Table khi requirement có nhiều điều kiện kết hợp (hạng hội viên, số tiền, kỳ hạn) để không bỏ sót luồng.\n- Bài tập: Lập Decision Table và viết Test Case cho Requirement lãi suất tiết kiệm Online: \n  + Kỳ hạn < 6 tháng (4.0%/năm). \n  + Kỳ hạn >= 6 tháng (Nếu số tiền < 100 triệu -> 6.0%/năm; >= 100 triệu -> 6.5%/năm). \n  + Khách VIP cộng thêm 0.2%/năm cho mọi trường hợp."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Giả định tiền gửi 80 triệu, kỳ hạn 9 tháng, VIP: lãi suất ví dụ = 6,0% + 0,2% = 6,2%/năm theo bộ quy tắc trong tài liệu, không phải lãi suất ngân hàng hiện hành."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Giải thích đầu vào kỳ hạn, số tiền, VIP và kết quả lãi suất."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết đủ các dòng bảng quyết định cho 3 nhóm kỳ hạn/giá trị và VIP/không VIP."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Thiết kế test cho biên 6 tháng, 100 triệu và yêu cầu thiếu quy định."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA1D4","title":"Banking 4: Phân vùng Tương đương (EP) & Phân tích Giá trị Biên (BVA)","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Equivalence partitioning nhóm các dữ liệu được kỳ vọng xử lý giống nhau; Boundary Value Analysis tập trung quanh nơi thay đổi hành vi."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 4 — Phân vùng Tương đương (EP) & Phân tích Giá trị Biên (BVA)"},{"type":"Paragraph","text":"- Lý thuyết: BVA test tại biên (Min-1, Min, Min+1, Max-1, Max, Max+1). EP chia dữ liệu thành các vùng hợp lệ và không hợp lệ.\n- Bài tập: Hạn mức chuyển tiền 24/7 Napas quy định: Tối thiểu 10.000 VNĐ, Tối đa 500.000.000 VNĐ/giao dịch. Xác định các giá trị cần test theo BVA và EP cho số tiền nhập vào."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Hạn mức giả định 10.000 đến 500.000.000 VND: các giá trị 9.999, 10.000, 10.001, 499.999.999, 500.000.000, 500.000.001 phải có Expected rõ."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Chia 3 vùng số tiền: dưới min, hợp lệ, trên max."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết test cho tất cả điểm biên và input trống / ký tự."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Bổ sung test kết hợp hạn mức ngày với hạn mức mỗi giao dịch, ghi giả định."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA1D5","title":"Banking 5: State Transition Testing (Chuyển đổi trạng thái)","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"State transition kiểm thử đường đi hợp lệ và không hợp lệ giữa các trạng thái, không chỉ kiểm tra giao diện hiển thị."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 5 — State Transition Testing (Chuyển đổi trạng thái)"},{"type":"Paragraph","text":"- Lý thuyết: Quản lý đối tượng theo máy trạng thái (State Machine). Test việc chuyển giữa các trạng thái dữ liệu (New, Active, Locked, Closed).\n- Bài tập: Vẽ sơ đồ/bảng chuyển đổi trạng thái và viết các Test Case tương ứng cho Thẻ Ghi Nợ (Debit Card): Khởi tạo (New) -> Kích hoạt (Active) -> Tạm khóa (do nhập sai PIN 3 lần) -> Khóa vĩnh viễn (Closed)."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Ví dụ thẻ: New → Active sau kích hoạt; Active → Locked sau 3 PIN sai; từ Locked không cho giao dịch; Closed là trạng thái cuối theo yêu cầu mẫu."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Vẽ bốn trạng thái thẻ và các hành động kích hoạt/khóa."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Tạo bảng chuyển trạng thái có cột Current, Event, Next, Expected."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Kiểm tra transition bị cấm và tính idempotent khi gửi sự kiện lặp."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA2D1","title":"Banking 6: Xử lý Luồng Ngoại lệ (Alternative & Exception Flows)","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Exception flow là luồng sai lệch do lỗi mạng, timeout, người dùng hủy, dữ liệu chồng chéo. Lỗi ở hệ thống thanh toán phải phân biệt chưa biết kết quả và thất bại xác nhận."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 6 — Xử lý Luồng Ngoại lệ (Alternative & Exception Flows)"},{"type":"Paragraph","text":"- Lý thuyết: Tập trung 70% vào Exception flow: Mất mạng, hết hạn session, lỗi đường truyền hệ thống, giao dịch bị treo.\n- Bài tập: Liệt kê ít nhất 6 kịch bản ngoại lệ (Exception Scenarios) có thể xảy ra khi người dùng thực hiện Thanh toán hóa đơn Điện/Nước trên Mobile Banking."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Thanh toán hóa đơn bị timeout sau khi gửi: giao diện không được tự báo thất bại nếu backend có thể đã thu tiền; cần trạng thái chờ xác minh và đối chiếu."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Liệt kê 6 tình huống ngoại lệ trong thanh toán hóa đơn."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết Expected và cách khôi phục cho từng tình huống."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Thiết kế test chống thanh toán trùng sau retry hoặc mở lại app."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA2D2","title":"Banking 7: Ôn tập Tuần 1 & Bài Test Tổng hợp Tư duy","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Mindmap test tổng hợp cần bao phủ happy path, dữ liệu, trạng thái, phân quyền, ngoại lệ, giao diện và khả năng quan sát."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 7 — Ôn tập Tuần 1 & Bài Test Tổng hợp Tư duy"},{"type":"Paragraph","text":"- Bài tập: Tình huống test feature \"Chuyển tiền qua Mã QR Code\": \n  1. Outline Mindmap các luồng cần test (dạng văn bản). \n  2. Viết 3 Test Cases quan trọng nhất (Happy path & Exception path).\n\n\n🔵 TUẦN 2: KỸ THUẬT NỀN TẢNG (SQL & API TESTING TRONG BANKING)"},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"QR transfer: QR hợp lệ → hiển thị người nhận; QR hỏng → báo lỗi; timeout → trạng thái chưa xác định cho đến khi tra soát. Đây là ba nhánh độc lập."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Vẽ mindmap văn bản 5 nhánh cho chuyển tiền QR."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết 3 test case quan trọng và gắn nhánh rủi ro."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Thiết kế thêm negative tests khi QR bị sửa dữ liệu hay hết hạn (môi trường thử nghiệm)."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA2D3","title":"Banking 8: SQL Cơ bản cho Tester","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"SQL SELECT đọc dữ liệu, WHERE lọc, ORDER BY sắp xếp, LIMIT lấy một số dòng; không cần biết lập trình trước khi đọc truy vấn."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 8 — SQL Cơ bản cho Tester"},{"type":"Paragraph","text":"- Lý thuyết: Cú pháp SELECT, WHERE, ORDER BY, LIKE, DISTINCT.\n- Bài tập: Cho bảng transactions (trans_id, account_no, amount, trans_type, created_at, status). Viết SQL query để: \n  1. Lấy tất cả giao dịch SUCCESS có amount > 10.000.000 VNĐ trong hôm nay. \n  2. Tìm 5 giao dịch gần đây nhất của account_no '1029384756'."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"SELECT trans_id, amount FROM transactions WHERE status='SUCCESS' AND amount>10000000 ORDER BY created_at DESC; -- dữ liệu minh họa trong DB kiểm thử"},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Giải thích ý nghĩa từng từ khóa SELECT/WHERE/ORDER BY."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết truy vấn 5 giao dịch gần đây nhất theo account_no giả lập."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Kiểm tra lọc theo ngày và múi giờ, tránh nhầm ngày server với ngày người dùng."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA2D4","title":"Banking 9: SQL Nâng cao - JOIN nhiều bảng Tài chính","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"JOIN ghép các bảng theo khóa quan hệ; INNER JOIN chỉ giữ bản ghi khớp, LEFT JOIN giữ cả bản ghi không có bên phải."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 9 — SQL Nâng cao - JOIN nhiều bảng Tài chính"},{"type":"Paragraph","text":"- Lý thuyết: Sử dụng INNER JOIN, LEFT JOIN để kết nối dữ liệu giữa customers, accounts, transactions.\n- Bài tập: Cho 3 bảng: customers (customer_id, full_name, phone_number), accounts (account_no, customer_id, balance, status), transactions (trans_id, account_no, amount, trans_type, status). Viết câu SQL JOIN 3 bảng để lấy: full_name, phone_number, account_no, amount của các giao dịch bị lỗi (status = 'FAILED')."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"SELECT c.full_name,a.account_no,t.amount FROM customers c JOIN accounts a ON a.customer_id=c.customer_id JOIN transactions t ON t.account_no=a.account_no WHERE t.status='FAILED';"},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Vẽ quan hệ customer → account → transaction."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết JOIN 3 bảng với alias dễ đọc."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Thử khách có tài khoản chưa có giao dịch, giải thích INNER vs LEFT JOIN."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA2D5","title":"Banking 10: SQL Banking - Aggregate, GROUP BY & Kiểm tra Lệch Sổ cái","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"GROUP BY gom bản ghi, HAVING lọc sau gom; phân biệt số giao dịch và tổng tiền. Đối soát phải dùng dữ liệu đã thống nhất trạng thái."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 10 — SQL Banking - Aggregate, GROUP BY & Kiểm tra Lệch Sổ cái"},{"type":"Paragraph","text":"- Lý thuyết: Sử dụng SUM(), COUNT(), AVG(), GROUP BY, HAVING để kiểm tra tổng phát sinh trong ngày.\n- Bài tập: Viết câu SQL tính tổng số tiền (SUM) và tổng số lượng (COUNT) giao dịch thành công của từng account_no trong ngày, chỉ hiển thị những tài khoản có tổng tiền giao dịch trong ngày > 100.000.000 VNĐ."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"SELECT account_no,COUNT(*) AS n,SUM(amount) AS total FROM transactions WHERE status='SUCCESS' GROUP BY account_no HAVING SUM(amount)>100000000;"},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Phân biệt WHERE và HAVING bằng lời."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết query số lượng, tổng tiền theo tài khoản."},{"type":"List Number","text":"Cấp 3 — Nâng cao: So sánh tổng tiền theo giao dịch và sổ phụ bằng dữ liệu mẫu, giải thích sai lệch."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA3D1","title":"Banking 11: RESTful API & JSON Ngân hàng","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"REST là cách thiết kế giao diện API; HTTP status mô tả kết quả request, JSON mang dữ liệu. 200 không đồng nghĩa nghiệp vụ chuyển tiền đã hoàn tất nếu response có status PENDING."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 11 — RESTful API & JSON Ngân hàng"},{"type":"Paragraph","text":"- Lý thuyết: HTTP Methods (GET, POST, PUT, DELETE), Status Codes (200, 400, 401, 403, 500), Cấu trúc JSON Object và Array.\n- Bài tập: Phân tích JSON Request/Response mẫu cho API Chuyển tiền và viết Checklist các status code cần test cho API này."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"POST /transfers với body {fromAccount:'A',toAccount:'B',amount:100000}; response mô phỏng {transactionId:'T001',status:'PENDING'}. Ghi rõ mô hình chỉ dùng thử nghiệm."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Xác định method, path, body và response cho API chuyển tiền giả lập."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Lập checklist cho 200, 400, 401, 403, 409, 500."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Thiết kế test retry an toàn cho 500/timeout và transactionId."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA3D2","title":"Banking 12: Thực hành Postman - Headers, Params & Auth Token","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Postman cho phép gửi request mà không viết frontend. Headers truyền Content-Type và Authorization, body chứa payload; token thật không nên xuất hiện trong repo hoặc screenshot."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 12 — Thực hành Postman - Headers, Params & Auth Token"},{"type":"Paragraph","text":"- Lý thuyết: Cấu hình Bearer Token, Content-Type: application/json, Params và Body (raw JSON).\n- Bài tập: Mô tả chi tiết một API Request POST /v1/auth/login trong Postman: Headers gồm gì? Body JSON gồm gì? Viết Response mẫu 200 OK trả về accessToken."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"POST /v1/auth/login; Content-Type: application/json; JSON {username:'demo',password:'test-only'}; 200 {accessToken:'MOCK-TOKEN',expiresIn:3600}."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Định nghĩa sự khác nhau giữa URL, header, body."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Thiết kế collection auth cho máy chủ giả lập."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Thử token thiếu/hết hạn và log không lộ thông tin nhạy cảm."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA3D3","title":"Banking 13: Viết Test Script Tự Động trong Postman","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Assertions là các điều kiện máy tự kiểm tra trong Postman. Cần test cả trạng thái HTTP, trường bắt buộc và giá trị nghiệp vụ."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 13 — Viết Test Script Tự Động trong Postman"},{"type":"Paragraph","text":"- Lý thuyết: Viết Javascript trong tab Tests của Postman để verify response status, response time, JSON body.\n- Bài tập: Viết script Postman JS test API POST /v1/transfer: \n  1. Check status code = 200. \n  2. Check trường status = \"SUCCESS\". \n  3. Check transactionId không bị null."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"pm.test('HTTP 200',()=>pm.response.to.have.status(200)); pm.test('has transactionId',()=>pm.expect(pm.response.json().transactionId).to.be.a('string'));"},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Đọc từng câu lệnh pm.test trong ví dụ."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Thêm assertion status SUCCESS và response time phù hợp môi trường test."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Tạo negative API tests cho amount không hợp lệ, đối chiếu expected error schema."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA3D4","title":"Banking 14: Ôn tập Tuần 2 & Bài Test Tổng hợp SQL + API","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Khi API trả 500, phân biệt lỗi ứng dụng và trạng thái giao dịch. Không kết luận tiền chưa trừ chỉ từ HTTP 500; cần correlation ID và đối soát."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 14 — Ôn tập Tuần 2 & Bài Test Tổng hợp SQL + API"},{"type":"Paragraph","text":"- Bài tập: API Chuyển tiền báo lỗi 500 Internal Server Error. \n  1. Dùng Postman xác định lỗi do Client hay Server? \n  2. Viết câu SQL kiểm tra trong DB xem account đã bị trừ tiền hay chưa và log bảng transactions.\n\n\n🔴 TUẦN 3: CHUYÊN SÂU NGHIỆP VỤ BANKING & BẢO MẬT (PENTEST)"},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"SELECT trans_id,status,amount FROM transactions WHERE trans_id='T-TEST-01'; -- chỉ chạy môi trường dữ liệu giả lập"},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Viết cách tái hiện request 500 có timestamp."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Dùng SQL kiểm tra trạng thái giao dịch mô phỏng."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Viết incident report liên kết request ID, log, DB và biện pháp hạn chế retry trùng."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA3D5","title":"Banking 15: Tổng quan Kiến trúc Ngân hàng (Core Banking & Payment Gateway)","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Core Banking quản lý các tài khoản và bút toán; API gateway là lớp truy cập dịch vụ. Hệ thống thanh toán liên ngân hàng có thêm thành phần trung gian và trạng thái bất đồng bộ."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 15 — Tổng quan Kiến trúc Ngân hàng (Core Banking & Payment Gateway)"},{"type":"Paragraph","text":"- Lý thuyết: Core Banking quản lý sổ cái. Kênh phân phối gọi qua ESB/API Gateway. Thanh toán liên ngân hàng qua NAPAS, CITAD, SWIFT.\n- Bài tập: Mô tả luồng đi của dòng tiền từ lúc bấm \"Chuyển tiền 24/7 từ Ngân hàng A sang B\" trên Mobile Banking -> ESB -> Core A -> NAPAS -> Core B và các điểm rủi ro."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Sơ đồ khái niệm: Mobile → API Gateway → Core A → Payment Rail → Core B; sự cố mỗi bước có thể làm chậm thông tin trả về, không nhất thiết mất dữ liệu."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Vẽ sơ đồ tuyến giao dịch 5 bước."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Đặt điểm kiểm tra và xác nhận ở từng bước."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Xây dựng test matrix timeout, duplicate, reconciliation mà không thao tác hệ thống thật."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA4D1","title":"Banking 16: Nghiệp vụ Tài khoản & Tiết kiệm (CASA & Online Savings)","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"CASA là tiền gửi không kỳ hạn; sổ tiết kiệm online là khoản tiền gửi có kỳ hạn. Tất toán trước hạn phụ thuộc điều khoản sản phẩm và quy định của ngân hàng."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 16 — Nghiệp vụ Tài khoản & Tiết kiệm (CASA & Online Savings)"},{"type":"Paragraph","text":"- Lý thuyết: CASA (tài khoản không kỳ hạn). Tiết kiệm online: Phong tỏa tiền CASA -> Tạo sổ. Công thức tính lãi tiền gửi.\n- Bài tập: Thiết kế bộ Test Case kiểm thử chức năng \"Tất toán sổ tiết kiệm Online trước hạn\" (tiền lãi bị tính theo lãi suất không kỳ hạn CASA)."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Ví dụ mô phỏng: gốc 20.000.000; nếu tất toán trước hạn, hệ thống chọn lãi suất không kỳ hạn mẫu thay vì lãi suất kỳ hạn. Không dùng số này cho quyết định tài chính thực tế."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Phân biệt mở, duy trì, tất toán sổ."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết test cho tất toán trước hạn và đúng hạn."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Thêm test tính lãi, làm tròn số, số dư CASA và tính nhất quán sau lỗi."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA4D2","title":"Banking 17: Chuyển tiền & Đối soát (Reconciliation & Timeout)","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Reconciliation đối chiếu hệ thống ghi nhận giao dịch giữa các bên. Timeout không đồng nghĩa thất bại; trạng thái PENDING cần được xác minh về sau."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 17 — Chuyển tiền & Đối soát (Reconciliation & Timeout)"},{"type":"Paragraph","text":"- Lý thuyết: Sự cố Timeout khi gọi NAPAS -> Trạng thái PENDING -> Batch Job/Đối soát cuối ngày cập nhật SUCCESS hoặc REVERSED (hoàn tiền).\n- Bài tập: Viết Test Cases cho luồng Xử lý Chuyển tiền bị Timeout (1. NAPAS trừ tiền thành công -> System update SUCCESS; 2. Thất bại -> System hoàn tiền REVERSED)."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"PENDING → SUCCESS nếu xác nhận hoàn tất; PENDING → REVERSED nếu đảo giao dịch hợp lệ. Tránh tự động đảo chỉ vì UI timeout."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Viết sơ đồ trạng thái SUCCESS/PENDING/REVERSED."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Tạo test chuyển trạng thái sau batch đối soát."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Kiểm tra không ghi nhận hai lần và xử lý sự kiện đến chậm."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA4D3","title":"Banking 18: Nghiệp vụ Tín dụng, Vay & Thẻ","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Thẻ tín dụng có hạn mức, dư nợ sao kê và lựa chọn số tiền thanh toán; khoản vay có yêu cầu xét duyệt và lịch thanh toán."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 18 — Nghiệp vụ Tín dụng, Vay & Thẻ"},{"type":"Paragraph","text":"- Lý thuyết: Vay online: Chấm điểm tín dụng -> Phê duyệt -> Giải ngân. Thẻ Credit: Hạn mức, Dư nợ, Sao kê, Thanh toán tối thiểu.\n- Bài tập: Viết Test Case cho chức năng \"Thanh toán dư nợ thẻ tín dụng\" với 3 lựa chọn: Thanh toán toàn bộ, thanh toán tối thiểu, thanh toán tùy chọn."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Ví dụ nợ 3.000.000: tùy chọn trả toàn bộ 3.000.000, tối thiểu theo chính sách mẫu, hoặc số tiền khác hợp lệ; dữ liệu test không đại diện chính sách ngân hàng thật."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Tạo 3 test case tương ứng ba cách thanh toán."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Thử vượt dư nợ, số tiền âm, lỗi cổng thanh toán."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Kiểm thử trạng thái bút toán và hiển thị dư nợ sau retry/timeout."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA4D4","title":"Banking 19: eKYC & Anti-Money Laundering (AML)","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"eKYC đối chiếu giấy tờ và xác thực người dùng; AML là phát hiện và xử lý tín hiệu giao dịch bất thường. Mọi test phải dùng tài khoản và dữ liệu giả được cấp phép."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 19 — eKYC & Anti-Money Laundering (AML)"},{"type":"Paragraph","text":"- Lý thuyết: eKYC (OCR, Liveness Detection, Face Matching). AML (Cảnh báo giao dịch bất thường sát hạn mức 500 triệu liên tục).\n- Bài tập: Viết Test Scenarios giả mạo (Spoofing) khuôn mặt và CCCD để test độ bảo mật của hệ thống eKYC."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Ví dụ: OCR đọc thiếu ngày sinh → yêu cầu xác minh lại, không tự duyệt. Giao dịch bị cảnh báo → chuyển kiểm tra, không gắn nhãn vi phạm chỉ vì một ngưỡng."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Phân biệt OCR, liveness, face matching."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Thiết kế test quyền riêng tư, dữ liệu không hợp lệ và quy trình xử lý cảnh báo."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Viết checklist kiểm thử phòng thủ, bảo vệ PII và audit log mà không sử dụng giấy tờ thật."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA4D5","title":"Banking 20: Pentest cơ bản cho Tester với Burp Suite (OWASP Top 10)","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Security QA kiểm thử quyền truy cập, validation và logic nghiệp vụ trong môi trường được ủy quyền. Không thử dịch vụ ngân hàng thực hoặc tài khoản không thuộc quyền mình."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 20 — Pentest cơ bản cho Tester với Burp Suite (OWASP Top 10)"},{"type":"Paragraph","text":"- Lý thuyết: IDOR, Parameter Tampering, SQL Injection, Broken Authentication.\n- Bài tập: Giả thiết bắt được Request POST /api/v1/transfer với body {\"fromAccount\": \"1111\", \"toAccount\": \"2222\", \"amount\": 1000000}. Mô tả 4 cách can thiệp payload để Pentest."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Ví dụ phòng thủ: khách A không được phép xem chi tiết tài khoản của khách B; hệ thống phải trả từ chối và log được event mà không tiết lộ dữ liệu."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Liệt kê các loại rủi ro OWASP thường gặp."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết negative tests cho quyền người dùng và trường dữ liệu không hợp lệ trên mock API."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Tạo checklist biện pháp bảo vệ, logging và xác minh bản vá trong test sandbox."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA5D1","title":"Banking 21: Ôn tập Tuần 3 & Bài Test Nghiệp vụ Ngân hàng + Security","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Security checklist liệt kê các hành vi cần bảo vệ; business checklist xác minh quy tắc sản phẩm. Với vay thấu chi, hai lớp yêu cầu phải được theo dõi độc lập."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 21 — Ôn tập Tuần 3 & Bài Test Nghiệp vụ Ngân hàng + Security"},{"type":"Paragraph","text":"- Bài tập: Thiết kế Security Checklist & Business Flow Checklist cho tính năng \"Đăng ký khoản vay thấu chi online\" trên Mobile Banking.\n\n\n🟡 TUẦN 4: AUTOMATION, PERFORMANCE & KỸ NĂNG LEADERSHIP"},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Luồng mẫu: đăng nhập → xác nhận điều kiện → gửi yêu cầu → kiểm tra → phê duyệt/từ chối. Test yêu cầu không được duyệt khi thiếu dữ liệu bắt buộc."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Viết 5 nghiệp vụ happy/negative cho vay thấu chi."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết 5 kiểm tra quyền truy cập và dữ liệu nhạy cảm."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Xây traceability từ yêu cầu đến kết quả kiểm thử và residual risks."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA5D2","title":"Banking 22: Performance Testing cơ bản với JMeter","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Performance testing đo hệ thống khi có tải, nhưng không bắn tải vào dịch vụ thật nếu không có quyền. Latency p90 là thời gian mà 90% request đạt hoặc nhanh hơn."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 22 — Performance Testing cơ bản với JMeter"},{"type":"Paragraph","text":"- Lý thuyết: Thread Group, Ramp-up, TPS, Response Time (90th percentile), Load/Stress testing.\n- Bài tập: Thiết lập kịch bản Load Test API POST /api/v1/payments (500 users, 10s ramp-up, 5 loops). Giải thích ý nghĩa TPS, Average Response Time, Error %."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Ví dụ sandbox 50 virtual users theo ramp-up 20 giây: ghi p90, throughput, error rate; so sánh baseline trước khi quyết định SLO. Bộ số tải từ tài liệu gốc chỉ áp dụng ở môi trường cho phép."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Phân biệt load test và stress test."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Thiết kế test plan JMeter cho sandbox với mục tiêu phù hợp."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Phân tích bottleneck dựa trên biểu đồ và đề xuất cải tiến có thể kiểm chứng."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA5D3","title":"Banking 23: API Automation với Postman + Newman CLI","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Newman chạy Postman Collection bằng CLI để lặp lại API tests. Tách collection, environment test và secret, không lưu token thật."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 23 — API Automation với Postman + Newman CLI"},{"type":"Paragraph","text":"- Lý thuyết: Export collection/environment JSON, chạy dòng lệnh Newman CLI.\n- Bài tập: Viết câu lệnh Newman hoàn chỉnh chạy file collection, file environment, xuất báo cáo HTML và CLI."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"newman run banking-collection.json -e sandbox-env.json --reporters cli,json --reporter-json-export report.json"},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Giải thích collection và environment."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết lệnh chạy và thu report."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Phân nhóm smoke/regression, xác định exit code và CI quality gate."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA5D4","title":"Banking 24: Automation UI cơ bản với Playwright","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"UI Automation bắt đầu từ một test đơn giản có locator ổn định, test data giả và assertion rõ. Không cần học toàn bộ lập trình trước khi chạy test mẫu."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 24 — Automation UI cơ bản với Playwright"},{"type":"Paragraph","text":"- Lý thuyết: Playwright test UI hiện đại. Cú pháp thao tác page.goto(), page.fill(), page.click().\n- Bài tập: Viết code Playwright (TypeScript/Python) tự động hóa: Vào trang Login -> Nhập user/pass -> Click Login -> Assert text \"Số dư tài khoản\"."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Playwright TS: test('login', async ({page}) => { await page.goto('/login'); await page.getByLabel('Username').fill('demo'); await page.getByRole('button',{name:'Login'}).click(); await expect(page.getByText('Dashboard')).toBeVisible(); });"},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Giải thích page, locator, fill, click, expect."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Chỉnh test thành luồng đăng nhập mock."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Thêm negative test, screenshot on failure và xử lý data test ổn định."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA5D5","title":"Banking 25: Automation UI Nâng cao - Page Object Model (POM)","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Page Object Model nhóm thao tác UI vào class để test ngắn, tránh lặp locator. POM không thay thế assertion nghiệp vụ rõ ràng."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 25 — Automation UI Nâng cao - Page Object Model (POM)"},{"type":"Paragraph","text":"- Lý thuyết: Mô hình POM tách biệt Locators/Actions khỏi Test Script để dễ bảo trì.\n- Bài tập: Tóm tắt kiến trúc POM. Với trang TransferPage, bạn sẽ thiết kế cấu trúc file và hàm như thế nào?"},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"class LoginPage { constructor(page){this.page=page;} async login(user){await this.page.getByLabel('Username').fill(user);await this.page.getByRole('button',{name:'Login'}).click();} }"},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Phân biệt class, method, locator bằng lời."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Tách LoginPage và test đăng nhập."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Review khả năng bảo trì và tránh giấu assertion quan trọng trong POM."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA6D1","title":"Banking 26: Tích hợp Automation vào CI/CD (GitHub Actions)","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"CI/CD chạy kiểm thử khi có thay đổi code; pipeline nên fail khi test fail thay vì báo thành công giả. Test staging không nên dùng secret production."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 26 — Tích hợp Automation vào CI/CD (GitHub Actions)"},{"type":"Paragraph","text":"- Lý thuyết: Tự động chạy automation test qua file cấu hình .github/workflows/test.yml.\n- Bài tập: Viết file YAML cơ bản cho GitHub Actions cài đặt Node.js và chạy Playwright Test khi push code."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Luồng: push → install deps → lint → unit/API tests → UI smoke → build. Khi test lỗi: lưu report và dừng deploy."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Kể tên 5 bước pipeline cơ bản."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết workflow YAML cho repo demo."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Thêm artifact test report và cache dependency, kiểm tra điều kiện branch."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA6D2","title":"Banking 27: Lập Test Plan & Test Strategy hoàn chỉnh","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Test plan trả lời phạm vi, người kiểm thử, môi trường, lịch, rủi ro và điều kiện kết thúc. Không nên dùng số lượng test pass thay cho nhận định rủi ro."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 27 — Lập Test Plan & Test Strategy hoàn chỉnh"},{"type":"Paragraph","text":"- Lý thuyết: Chuẩn IEEE 829: Scope, Resource, Schedule, Environment, Entry/Exit Criteria, Risks.\n- Bài tập: Viết Scope và Exit Criteria trong Test Plan cho dự án \"Nâng cấp Hệ thống Thanh toán Chuyển tiền QR Code\"."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Exit criteria mẫu: 100% critical flows được chạy; 0 blocker chưa xử lý; lỗi medium được phê duyệt rủi ro; UAT owner ký xác nhận."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Viết Scope/Out-of-scope cho chuyển tiền QR."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Lập Entry/Exit criteria theo rủi ro."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Viết test strategy kết hợp manual, API, automation, security và performance."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA6D3","title":"Banking 28: Ước lượng (Estimation) & Quản lý Rủi ro","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Estimation bằng 3-point cân nhắc lạc quan, khả năng nhất và bi quan; công thức PERT (O + 4M + P)/6 chỉ là một giả định đánh giá, không phải cam kết chắc chắn."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 28 — Ước lượng (Estimation) & Quản lý Rủi ro"},{"type":"Paragraph","text":"- Lý thuyết: WBS, 3-Point Estimation: E = (O + 4M + P) / 6. Quản lý rủi ro dự án.\n- Bài tập: Tính tổng thời gian Estimate cho 3 task: Task A (O=2h, M=4h, P=8h), Task B (O=4h, M=6h, P=14h), Task C (O=1h, M=2h, P=3h) theo công thức 3-Point Estimation."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Task A (2,4,8): 4,33h; B (4,6,14): 7h; C (1,2,3): 2h. Tổng ~13,33h trước contingency."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Tính PERT cho 3 tasks của giáo trình."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Tạo WBS và ước lượng ngày công QA."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Bổ sung rủi ro phụ thuộc test data, môi trường và khả năng automation bị flaky."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA6D4","title":"Banking 29: Kỹ năng Senior/Lead - Review Test Case, Mentoring & Reporting","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Senior QA review yêu cầu hỏi đúng rủi ro và chứng cứ; feedback mô tả hành vi, tác động, cách sửa, không đánh giá con người."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 29 — Kỹ năng Senior/Lead - Review Test Case, Mentoring & Reporting"},{"type":"Paragraph","text":"- Lý thuyết: Review test case cho Junior, Jira metrics, Báo cáo chất lượng cho PO/BOD.\n- Bài tập: Viết comment feedback chuyên nghiệp để hướng dẫn chỉnh sửa cho Junior Tester viết test case lan man và thiếu exception flow."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Feedback mẫu: 'TC-05 chưa ghi dữ liệu đầu vào và Expected. Vui lòng bổ sung giới hạn số tiền, status code và kiểm tra transactionId để người khác tái hiện.'"},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Chọn 3 tiêu chí review test case."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Viết nhận xét xây dựng cho bài test chưa có exception flows."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Tạo weekly test status report có kết quả, rủi ro và đề xuất."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]},{"id":"QA6D5","title":"Banking 30: Bài tập Tổng hợp Tốt nghiệp Senior/Lead Tester","sections":[{"title":"A. Giải thích từ số 0 (Banking QA)","blocks":[{"type":"Heading 2","text":"Khái niệm và cách tư duy"},{"type":"Paragraph","text":"Capstone kết nối yêu cầu → test design → API/SQL → security → performance → automation → báo cáo. Chỉ dùng dữ liệu ngân hàng hư cấu, không khai thác hệ thống thật."},{"type":"Callout","text":"Không yêu cầu biết code trước khi bắt đầu. Với SQL/API/Automation, hãy học từ mẫu dữ liệu trước, sau đó đọc từng cú pháp. Chỉ dùng tài khoản thử nghiệm và môi trường được phép."}]},{"title":"B. Nội dung giáo trình Banking gốc","blocks":[{"type":"Heading 2","text":"Ngày 30 — Bài tập Tổng hợp Tốt nghiệp Senior/Lead Tester"},{"type":"Paragraph","text":"- Bài tập: Dự án \"Mở Thẻ Tín Dụng Trực Tuyến & Phê Duyệt Hạn Mức Tự Động\" trên Mobile Banking.\n  1. Liệt kê rủi ro và giải pháp phòng ngừa.\n  2. Thiết kế Test Strategy (Functional, API, Security, Performance, Automation).\n  3. Viết 2 câu SQL nâng cao kiểm tra dữ liệu hạn mức thẻ sau phê duyệt."},{"type":"Callout","text":"Trích nội dung từ giáo trình QA Banking 30 ngày đã cung cấp. Các phần tiếp theo là ví dụ và thực hành bổ sung, không thay thế tài liệu gốc."}]},{"title":"C. Ví dụ có phân tích","blocks":[{"type":"Heading 2","text":"Mẫu tham khảo"},{"type":"Paragraph","text":"Feature mẫu phát hành thẻ: 신청 → review → approval/reject → issuing; đảm bảo hạn mức hợp lệ, phân quyền chặt và dữ liệu nhất quán."},{"type":"List Bullet","text":"Trước khi thử: ghi yêu cầu, dữ liệu mô phỏng và expected result."},{"type":"List Bullet","text":"Trong khi thử: ghi actual result và bằng chứng; tránh kết luận từ một dấu hiệu không đầy đủ."},{"type":"List Bullet","text":"Sau khi thử: phân tích tác động nghiệp vụ, trường hợp ngoại lệ và regression."}]},{"title":"D. Luyện 3 cấp độ & 2 ứng dụng","blocks":[{"type":"Heading 2","text":"Bài tập chia câu — làm từ dễ đến khó"},{"type":"List Number","text":"Cấp 1 — Nền tảng: Vẽ luồng đăng ký thẻ và 6 test cases."},{"type":"List Number","text":"Cấp 2 — Thực hành nghiệp vụ: Lập chiến lược kiểm thử đủ năm nhóm và hai query SQL trên dữ liệu mẫu."},{"type":"List Number","text":"Cấp 3 — Nâng cao: Nộp test plan, bug report, automation demo, risk register, summary và self-review."},{"type":"List Number","text":"AI Tourism: chọn một thao tác tương tự trong quy trình bán tour/booking và ghi 2 test case gồm dữ liệu, bước và expected result."},{"type":"List Number","text":"AI Stock: kiểm tra watchlist/giá dữ liệu mẫu, viết 2 test case cho tình huống bình thường và dữ liệu lỗi."}]},{"title":"E. Kiểm tra kết quả & tiêu chí đạt","blocks":[{"type":"Heading 2","text":"Đối chiếu lời giải"},{"type":"Paragraph","text":"Đối chiếu phần ví dụ đã phân tích và yêu cầu gốc. Không chấm đạt chỉ vì đã nhập một đoạn văn; phải có đầu vào, kết quả kỳ vọng, kết quả thực tế giả định hoặc bằng chứng chạy thử."},{"type":"List Bullet","text":"2 điểm: hiểu khái niệm và quy trình; 2 điểm: test case/bài giải chính xác; 2 điểm: xử lý negative/boundary; 2 điểm: bằng chứng hoặc mô tả kiểm chứng; 2 điểm: liên hệ nghiệp vụ và rủi ro."},{"type":"Callout","text":"Nếu chưa làm được, quay lại ví dụ và làm lại câu dễ trước khi lên câu khó."}]}]}];const all=window.CURRICULUM?.weeks||[];for(const x of arr){const d=all.flatMap(w=>w.days).find(d=>d.id===x.id);if(!d)continue;if(!d.sections.some(s=>s.title==='A. Giải thích từ số 0 (Banking QA)')){d.title=x.title;d.sections=[...x.sections,...d.sections];}}const groups=all.filter(w=>w.days?.some(d=>/^QA\d+D\d+$/.test(d.id)));for(let i=0;i<groups.length;i++){groups[i].title='QA Banking từ số 0 · Ngày '+String(i*5+1).padStart(2,'0')+'–'+String(i*5+5).padStart(2,'0');}})();